def load() -> pd.DataFrame:
    import os, glob
    import pandas as pd

    base = 'data/astronomy/input/swarm/POD'
    rows = []
    if os.path.exists(base):
        rows.append({'path': base, 'type': 'exists'})
        # list two levels deep
        for p in sorted(glob.glob(base + '/**', recursive=True))[:5000]:
            if os.path.isdir(p):
                continue
            if p.lower().endswith('.sp3') or 'SP3' in p or 'sp3' in p:
                rows.append({'path': p, 'type': 'file'})
    else:
        rows.append({'path': base, 'type': 'missing'})

    # also glob broader in case folder differs
    for pat in [
        'data/astronomy/input/swarm/**/*.sp3',
        'data/astronomy/input/**/*.sp3',
        'data/astronomy/input/swarm/POD/**/*.SP3',
    ]:
        matches = sorted(glob.glob(pat, recursive=True))
        rows.append({'path': pat, 'type': f'pattern_matches={len(matches)}'})
        for m in matches[:20]:
            rows.append({'path': m, 'type': 'match_sample'})

    return pd.DataFrame(rows)

