def load() -> pd.DataFrame:
    import numpy as np
    import pandas as pd

    path = 'data/astronomy/input/mock_tiegcm_grid_sept2019.npz'
    z = np.load(path, allow_pickle=True)

    # Required grids
    lat_grid = np.asarray(z['lat_grid'], dtype=float)
    lon_grid = np.asarray(z['lon_grid'], dtype=float)
    alt_grid = np.asarray(z['alt_grid'], dtype=float)

    # Find candidate 3D (or more) fields beyond the grids
    grid_keys = {'lat_grid', 'lon_grid', 'alt_grid'}
    candidates = []
    for k in z.files:
        if k in grid_keys:
            continue
        arr = np.asarray(z[k])
        if arr.ndim >= 3:
            candidates.append((k, arr))

    # Pick the first candidate if present
    field_key = None
    field = None
    if len(candidates) > 0:
        field_key, field = candidates[0]
        field = np.asarray(field, dtype=float)

    def _safe_minmax(a):
        try:
            return float(np.nanmin(a)), float(np.nanmax(a))
        except Exception:
            return None, None

    fmin, fmax = (None, None) if field is None else _safe_minmax(field)

    out = {
        'lat_grid': [lat_grid],
        'lon_grid': [lon_grid],
        'alt_grid': [alt_grid],
        'field_key': [field_key],
        'field': [field],
        'keys': [list(z.files)],
        'field_shape': [None if field is None else tuple(field.shape)],
        'field_dtype': [None if field is None else str(field.dtype)],
        'field_min': [fmin],
        'field_max': [fmax],
    }

    return pd.DataFrame(out)
